# Ce code calcule l'énergie consommée en kWh et estime le coût.

def calculer_energie_kwh(puissance_kw, temps_heures, prix_par_kwh=0.25):
    """
    Calcule l'énergie en kilowattheures (kWh) et estime le coût.
    Formule : E(kWh) = Puissance(kW) * Temps(heures)
    """
    energie_kwh = puissance_kw * temps_heures
    cout = energie_kwh * prix_par_kwh
    
    print(f"--- Appareil de {puissance_kw} kW ---")
    print(f"Temps d'utilisation : {temps_heures} heures")
    print(f"Énergie consommée : {energie_kwh} kWh")
    print(f"Coût estimé : {cout:.2f} £")
    print("-" * 30)
    
    return energie_kwh, cout

# --- Tests de la fonction ---
print("=== CALCULATEUR DE CONSOMMATION ÉLECTRIQUE ===\n")

# Test 1 : Un radiateur de 1.5 kW allumé pendant 4 heures
calculer_energie_kwh(1.5, 4)

